"""EventModal -- Google-Calendar-style event creator / editor."""

import from endpoints { Event, create_event, update_event }
import from .ui.dialog { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter }
import from .ui.button { Button }
import from .ui.input { Input }
import from .ui.textarea { Textarea }
import from .ui.label { Label }


def parse_int(s: str, fallback: int) -> int {
    try {
        return int(s);
    } except ValueError {
        return fallback;
    }
}


def:pub EventModal(
    day: int,
    year: int,
    month: int,
    existing: Event | None,
    day_events: list[Event],
    onClose: Callable[[], None],
    onSaved: Callable[[Event], None],
    onStart: Callable[[Event], None],
    onOpenEvent: Callable[[Event], None]
) -> JsxElement {
    is_edit = existing is not None;

    has title: str = existing.title if existing is not None else "";
    has description: str = existing.description if existing is not None else "";
    has hour_s: str = str(existing.hour) if existing is not None else "09";
    has minute_s: str = str(existing.minute) if existing is not None else "00";
    has work_min_s: str = str(existing.work_min) if existing is not None else "25";
    has break_min_s: str = str(existing.break_min) if existing is not None else "5";
    has cycles_s: str = str(existing.cycles) if existing is not None else "1";
    has show_advanced: bool = False;
    has saving: bool = False;

    def set_title(e: ChangeEvent) -> None { title = e.target.value; }
    def set_description(e: ChangeEvent) -> None { description = e.target.value; }
    def set_hour(e: ChangeEvent) -> None { hour_s = e.target.value; }
    def set_minute(e: ChangeEvent) -> None { minute_s = e.target.value; }
    def set_work_min(e: ChangeEvent) -> None { work_min_s = e.target.value; }
    def set_break_min(e: ChangeEvent) -> None { break_min_s = e.target.value; }
    def set_cycles(e: ChangeEvent) -> None { cycles_s = e.target.value; }
    def toggle_advanced -> None { show_advanced = not show_advanced; }
    def start_this -> None { onStart(existing); }

    async def submit(e: FormEvent) -> None {
        e.preventDefault();
        if not title.strip() { return; }
        saving = True;
        h = parse_int(hour_s, 0);
        mn = parse_int(minute_s, 0);
        w = parse_int(work_min_s, 25);
        b = parse_int(break_min_s, 5);
        c = parse_int(cycles_s, 1);
        if is_edit {
            ev = await update_event(
                jid(existing), year, month, day, h, mn,
                title, description, w, b, c
            );
            if ev is not None { onSaved(ev); }
        } else {
            ev = await create_event(
                year, month, day, h, mn,
                title, description, w, b, c
            );
            onSaved(ev);
        }
        saving = False;
        onClose();
    }

    def handle_open_change(open: bool) -> None {
        if not open { onClose(); }
    }

    <Dialog open={True} onOpenChange={handle_open_change}>
        <DialogContent className="max-w-lg">
            <DialogHeader>
                <DialogTitle>
                    {("Edit event" if is_edit else "New event") + " -- Sept " + str(day)}
                </DialogTitle>
            </DialogHeader>

            {if not is_edit and len(day_events) > 0 {
                <div className="flex flex-col gap-1 mb-2 border-b border-border pb-3">
                    <span className="text-xs text-muted-foreground uppercase tracking-wide">
                        Existing events
                    </span>
                    {for ev in day_events {
                        <button
                            key={jid(ev)}
                            className="text-left text-sm p-2 rounded hover:bg-accent flex justify-between"
                            onClick={lambda () { onOpenEvent(ev); }}
                        >
                            <span>{ev.title}</span>
                            <span className="font-mono text-muted-foreground">
                                {f"{ev.hour:02}:{ev.minute:02}"}
                            </span>
                        </button>
                    }}
                </div>
            }}

            <form onSubmit={submit} className="flex flex-col gap-3">
                <div className="flex flex-col gap-1">
                    <Label htmlFor="ev-title">Title</Label>
                    <Input
                        id="ev-title"
                        value={title}
                        onChange={set_title}
                        placeholder="What are you doing?"
                        autoFocus={True}
                    />
                </div>

                <div className="flex gap-2 items-end">
                    <div className="flex flex-col gap-1">
                        <Label htmlFor="ev-hour">Hour</Label>
                        <Input
                            id="ev-hour"
                            className="w-16"
                            value={hour_s}
                            onChange={set_hour}
                        />
                    </div>
                    <span className="pb-2 text-muted-foreground">:</span>
                    <div className="flex flex-col gap-1">
                        <Label htmlFor="ev-min">Min</Label>
                        <Input
                            id="ev-min"
                            className="w-16"
                            value={minute_s}
                            onChange={set_minute}
                        />
                    </div>
                </div>

                <div className="flex flex-col gap-1">
                    <Label htmlFor="ev-desc">Description</Label>
                    <Textarea
                        id="ev-desc"
                        value={description}
                        onChange={set_description}
                        placeholder="Notes for this event"
                        rows={3}
                    />
                </div>

                <button
                    type="button"
                    className="text-xs text-primary text-left hover:underline"
                    onClick={toggle_advanced}
                >
                    {("Hide" if show_advanced else "Show") + " advanced (pomodoro settings)"}
                </button>

                {if show_advanced {
                    <div className="grid grid-cols-3 gap-2 p-3 border border-border rounded">
                        <div className="flex flex-col gap-1">
                            <Label htmlFor="ev-work">Work (min)</Label>
                            <Input
                                id="ev-work"
                                value={work_min_s}
                                onChange={set_work_min}
                            />
                        </div>
                        <div className="flex flex-col gap-1">
                            <Label htmlFor="ev-break">Break (min)</Label>
                            <Input
                                id="ev-break"
                                value={break_min_s}
                                onChange={set_break_min}
                            />
                        </div>
                        <div className="flex flex-col gap-1">
                            <Label htmlFor="ev-cycles">Cycles</Label>
                            <Input
                                id="ev-cycles"
                                value={cycles_s}
                                onChange={set_cycles}
                            />
                        </div>
                    </div>
                }}

                <DialogFooter className="mt-2 flex gap-2 justify-end">
                    <Button type="button" variant="ghost" onClick={onClose}>Cancel</Button>
                    {if is_edit {
                        <Button
                            type="button"
                            variant="outline"
                            onClick={start_this}
                        >
                            Start now
                        </Button>
                    }}
                    <Button type="submit" disabled={saving or not title.strip()}>
                        {"Save" if is_edit else "Create"}
                    </Button>
                </DialogFooter>
            </form>
        </DialogContent>
    </Dialog>
}
