def linkRef(url: str) -> str {
    parts = [
        p
        for p in url.split("/")
        if p
    ];
    if parts {
        tail = parts[-1];
        digits = True;
        for ch in tail {
            if ch not in "0123456789" {
                digits = False;
            }
        }
        if digits and tail {
            return "#" + tail;
        }
    }
    return "link";
}

def prettyDate(iso: str) -> str {
    d = new(Date, iso + "T00:00:00");
    days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    months = [
        "Jan",
        "Feb",
        "Mar",
        "Apr",
        "May",
        "Jun",
        "Jul",
        "Aug",
        "Sep",
        "Oct",
        "Nov",
        "Dec"
    ];
    return days[int(d.getDay())]
        + ", "
        + months[int(d.getMonth())]
        + " "
        + str(int(d.getDate()));
}
